Object.assign(I18N.de, { script: 'Schrift', scr_standard: 'Mushaf Standard', scr_uthmani: 'Osmanisch', scr_indopak: 'IndoPak', scr_plain: 'Ohne Diakritika', tjColors: 'Tajwîd-Farben', tjColorsSub: 'Regeln farbig markieren – Legende über ⓘ oben', tjColorsNo: 'Nur bei „Mushaf Standard“ und „Osmanisch“', scrOffline: 'Schrift konnte nicht geladen werden – bitte einmal mit Internet öffnen.',
  tj_silent: 'Nicht gesprochen (grau)', tj_silentT: 'Grau markierte Buchstaben werden im Lesefluss nicht ausgesprochen: das Hamzat al-Wasl (ٱ) mitten im Satz, das Lâm vor Sonnenbuchstaben und stumme Buchstaben wie das Alif nach dem Wâw der Mehrzahl (كَفَرُوا۟).',
  tjAuto: 'Die Farben im Koran werden automatisch aus der Schreibweise ermittelt. Abgeglichen mit einem unabhängigen Tajwîd-Datensatz stimmen sie zu rund 95 % überein – in Einzelfällen (v. a. bei Sonderlesungen) kann eine Stelle fehlen oder abweichen.' });
Object.assign(I18N.tr, { script: 'Yazı', scr_standard: 'Mushaf Standart', scr_uthmani: 'Osmanlı', scr_indopak: 'IndoPak', scr_plain: 'Harekesiz', tjColors: 'Tecvid renkleri', tjColorsSub: 'Kuralları renklendir – açıklama yukarıdaki ⓘ ile', tjColorsNo: 'Sadece „Mushaf Standart“ ve „Osmanlı“ yazısında', scrOffline: 'Yazı yüklenemedi – lütfen bir kez internetle açın.',
  tj_silent: 'Okunmayan harfler (gri)', tj_silentT: 'Gri harfler okurken telaffuz edilmez: cümle içindeki vasl hemzesi (ٱ), şemsî harflerden önceki lâm ve çoğul vavından sonraki elif gibi.',
  tjAuto: 'Kur\'an\'daki renkler yazımdan otomatik belirlenir; bağımsız bir tecvid veri setiyle yaklaşık %95 uyumludur. Nadiren bir yer eksik veya farklı olabilir.' });
